ChromeUtils.idleDispatch(
  () => {
    if (!Services.startup.shuttingDown) {
      const startTime = ChromeUtils.now();
      try {
        task.task();
      } catch (ex) {
        console.error(ex);
      } finally {
        ChromeUtils.addProfilerMarker("startupIdleTask", startTime);
      }
    }
  },
  task.timeout ? { timeout: task.timeout } : undefined
);
